def build_backtest_intervals(
    spx: dict[str, Any],
    regimes: dict[str, dict[str, Any]],
    config: E1RSidecarConfig,
) -> list[tuple[str, str]]:
    dates = [
        d for d in spx["dates"]
        if config.start_date <= d <= config.end_date
        and d in regimes
    ]
    dates = sorted(dates)
    return list(zip(dates[:-1], dates[1:]))
